const CACHE='aeroping-shell-v8';
const FILES=['./','./index.html','./styles.css?v=8','./app.js?v=8','./flight-search-ui.js?v=8','./push-notifications.js?v=8','./icon-192.png','./icon-512.png','./core.js?v=8','./localities.js?v=8','./localities-data.js?v=8','./cloud-v2.js?v=8','./google-auth.js?v=8','./shared-ui.js?v=8','./site-config.js','./profile.js','./icon.svg','./manifest.webmanifest'];
self.addEventListener('install',e=>{e.waitUntil(caches.open(CACHE).then(c=>c.addAll(FILES)));self.skipWaiting();});
self.addEventListener('activate',e=>{e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('aeroping-shell-')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim()));});
// Push works while the page is closed, after permission on this device.
self.addEventListener('push',e=>{let d={};try{d=e.data.json();}catch{}e.waitUntil(self.registration.showNotification(String(d.title||'Um novo ping no radar'),{body:String(d.body||'Abra o AeroPing para conferir.'),icon:'./icon-192.png',badge:'./icon-192.png',tag:d.id||'aeroping-ping',data:{url:new URL('./#alertas',self.registration.scope).href}}));});
self.addEventListener('notificationclick',e=>{e.notification.close();const target=new URL('./#alertas',self.registration.scope).href;e.waitUntil(clients.matchAll({type:'window',includeUncontrolled:true}).then(async windows=>{const existing=windows.find(w=>w.url.startsWith(self.registration.scope));if(existing){await existing.navigate(target);return existing.focus();}return clients.openWindow(target);}));});
self.addEventListener('fetch',e=>{if(e.request.method!=='GET'||new URL(e.request.url).origin!==self.location.origin)return;const url=new URL(e.request.url);if(!FILES.some(f=>new URL(f,self.registration.scope).pathname===url.pathname))return;e.respondWith(fetch(e.request).then(r=>{if(r.ok){const clone=r.clone();e.waitUntil(caches.open(CACHE).then(c=>c.put(e.request,clone)));}return r;}).catch(()=>caches.match(e.request)));});
